create or replace function private.record_product_stock_change() returns trigger language plpgsql security definer set search_path to '' as $$ declare v_key text := nullif(private.inventory_context_value(), ''); begin if new.stock is distinct from old.stock and (select auth.uid()) is not null then if v_key is null then insert into public.inventory_ledger(product_id,seller_id,quantity_change,reason,reference_type,reference_id,actor_id) values(new.id,new.seller_id,new.stock-old.stock,'adjustment','product',new.id,(select auth.uid())); else perform private.record_inventory_sale(new.id,old.stock-new.stock,v_key::uuid,new.seller_id); end if; end if; return new; end; $$;
